using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace ScoreModern {
 public sealed partial class Editor {
  internal void CheckIntegratedUi(string output){Directory.CreateDirectory(output);byte[] before=score.Encode();var oldMode=NativeNotationView.Mode;bool oldRulers=NativeWorkspaceGuides.Rulers,oldPage=NativeWorkspaceGuides.PageGap;float oldHeight=NativeWorkspaceGuides.RulerHeight,oldWidth=NativeWorkspaceGuides.RulerWidth;bool oldStrict=NativeScoreBehaviour.Enabled;NativeScoreBehaviour.Set(true,false);var oldPalette=NativeScreenPalette.Read(source);NativeScoreBehaviour.Set(oldStrict,false);string[] keys={"colour-notation","colour-background","colour-text","colour-edit"};string[] saved=keys.Select(NativeSettings.Read).ToArray();try{
   NativeWorkspaceGuides.Rulers=true;NativeWorkspaceGuides.PageGap=true;NativeWorkspaceGuides.PageGapPoints=6;NativeWorkspaceGuides.RulerHeight=48;NativeWorkspaceGuides.RulerWidth=36;
   foreach(var mode in new[]{NotationView.Vector,NotationView.Dat,NotationView.DatPixels,NotationView.DatViewport}){NativeNotationView.Set(mode,false);RefreshPageFrame();ClientSize=new Size(1800,1000);PerformLayout();Application.DoEvents();if(!rulerTop.Visible||!verticalRuler.Visible)throw new Exception("Missing reserved rulers.");Rectangle view=rulerHost.RectangleToClient(viewport.RectangleToScreen(viewport.ClientRectangle)),topRect=rulerHost.RectangleToClient(rulerTop.RectangleToScreen(rulerTop.ClientRectangle)),leftRect=rulerHost.RectangleToClient(verticalRuler.RectangleToScreen(verticalRuler.ClientRectangle));if(view.IntersectsWith(topRect)||view.IntersectsWith(leftRect))throw new Exception("Rulers overlap graphics viewport.");if(canvas.Parent!=viewport)throw new Exception("Pointer coordinate parent changed.");Point location=new Point(Math.Min(200,canvas.Width-1),Math.Min(200,canvas.Height-1));Point canvasPoint=canvas.PointToClient(horizontalRuler.PointToScreen(horizontalRuler.PointToClient(canvas.PointToScreen(location))));if(canvasPoint!=location)throw new Exception("Ruler pointer mapping changed.");canvas.GuidePointer(location);using(var image=new Bitmap(horizontalRuler.Width,horizontalRuler.Height)){horizontalRuler.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(output,"ruler-"+mode+".png"));}var camera=canvas.CameraOffset;canvas.GuidePointer(null);if(canvas.CameraOffset!=camera)throw new Exception("Pointer moved score camera.");}
   NativeNotationView.Set(NotationView.Vector,false);RefreshPageFrame();var menu=viewport.ContextMenuStrip;var late=menu.Items.Add("Test extension");menu.Show(viewport,new Point(1,1));Application.DoEvents();if(menu.Items[menu.Items.Count-1].Text!="Preferences..."||!(menu.Items[menu.Items.Count-2] is ToolStripSeparator))throw new Exception("Preferences is not last.");menu.Close();menu.Items.Remove(late);late.Dispose();
   Color arbitrary=Color.FromArgb(17,63,129);foreach(string key in keys)NativeSettings.WriteAllText(key,arbitrary.ToArgb().ToString("X8"));NativeScoreBehaviour.Set(false,false);var palette=NativeScreenPalette.Read(source);if(palette.Graphics!=arbitrary||palette.Background!=arbitrary||palette.Text!=arbitrary||palette.Edit!=arbitrary)throw new Exception("Windows RGB override lost.");NativeScoreBehaviour.Set(true,false);palette=NativeScreenPalette.Read(source);if(palette.Graphics!=oldPalette.Graphics||palette.Background!=oldPalette.Background)throw new Exception("Strict SCORE palette changed.");if(!before.SequenceEqual(score.Encode()))throw new Exception("UI changed MUS data.");
   NativeWorkspaceGuides.RulerHeight=160;NativeWorkspaceGuides.RulerWidth=160;RefreshRulerLayout();if(rulerTop.Height!=(int)Math.Ceiling(160*NativeDisplay.Scale(this))||verticalRuler.Width!=(int)Math.Ceiling(160*NativeDisplay.Scale(this)))throw new Exception("Ruler size is not DPI aware.");
   File.WriteAllText(Path.Combine(output,"integrated-ui.txt"),"PASS reserved ruler geometry and pointer round-trips in all four modes; ruler rendering; menu extension ordering; arbitrary RGB and Strict SCORE palette; DPI-aware sizing; unchanged MUS data.\r\nActual desktop capture at 175% remains separate visual QA.");
  }finally{for(int i=0;i<keys.Length;i++)NativeSettings.WriteAllText(keys[i],saved[i]);NativeScoreBehaviour.Set(oldStrict,false);NativeWorkspaceGuides.Rulers=oldRulers;NativeWorkspaceGuides.PageGap=oldPage;NativeWorkspaceGuides.RulerHeight=oldHeight;NativeWorkspaceGuides.RulerWidth=oldWidth;NativeNotationView.Set(oldMode,false);RefreshPageFrame();}Console.WriteLine("PASS integrated UI checks");
  }
 }
 public static class NativeIntegratedUiChecks {public static int Run(string[] args){try{using(var editor=new Editor(args[1],args[2])){editor.Show();Application.DoEvents();editor.CheckIntegratedUi(args[3]);editor.Close();}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}}
